#include <bits/stdc++.h>
using namespace std;using R=vector<unsigned>;using Z=long long;
void need(bool b,string s){if(!b)throw runtime_error(s);}
R clone_last(R const&T,int m){int n=T.size(),r=n-1;R U(r+m);for(int a=0;a<r;a++){U[a]=T[a]&((1u<<r)-1);for(int k=0;k<m;k++)if(T[a]>>r&1)U[a]|=1u<<(r+k);}for(int k=0;k<m;k++){U[r+k]=T[r];for(int l=k+1;l<m;l++)U[r+k]|=1u<<(r+l);}return U;}
Z walk(R const&T){int n=T.size(),N=1<<n;__int128 ans=0;vector<__int128>d(n),e(n);for(int S=1;S<N;S++){fill(d.begin(),d.end(),0);for(int a=0;a<n;a++)if(S>>a&1)d[a]=1;for(int t=1;t<n;t++){fill(e.begin(),e.end(),0);for(int a=0;a<n;a++)if(d[a]){unsigned b=T[a]&S;while(b){int x=__builtin_ctz(b);b&=b-1;e[x]+=d[a];}}d.swap(e);}__int128 h=accumulate(d.begin(),d.end(),(__int128)0);ans+=(n-__builtin_popcount((unsigned)S))%2?-h:h;}need(ans>0&&ans<LLONG_MAX,"count range");return(Z)ans;}
vector<Z> gap(R const&T){int n=T.size()-1,r=n;vector<int>p(n);iota(p.begin(),p.end(),0);vector<Z>out(n+2);do{vector<Z>a(n+2),b(n+2);a[0]=1;a[1]=T[r]>>p[0]&1;bool live=true;for(int j=0;j<n-1;j++){int x=p[j],y=p[j+1];bool edge=T[x]>>y&1,cut=(T[x]>>r&1)&&(T[r]>>y&1);if(!edge&&!cut){live=false;break;}fill(b.begin(),b.end(),0);for(int k=0;k<=n;k++){if(edge)b[k]+=a[k];if(cut)b[k+1]+=a[k];}a.swap(b);}if(!live)continue;for(int k=0;k<=n;k++){out[k]+=a[k];if(T[p.back()]>>r&1)out[k+1]+=a[k];}}while(next_permutation(p.begin(),p.end()));return out;}
int modules(R const&T){int n=T.size(),F=(1<<n)-1,count=0;for(int M=1;M<F;M++){if(__builtin_popcount((unsigned)M)<2)continue;bool good=true;for(int a=0;a<n;a++)if(!(M>>a&1)){unsigned z=T[a]&M;if(z&&z!=(unsigned)M){good=false;break;}}count+=good;}return count;}
int automorphisms(R const&T){int n=T.size(),count=0;vector<int>f(n,-1),deg(n);for(int a=0;a<n;a++)deg[a]=__builtin_popcount(T[a]);function<void(int,unsigned)>go=[&](int a,unsigned used){if(a==n){count++;return;}for(int b=0;b<n;b++)if(!(used>>b&1)&&deg[a]==deg[b]){bool ok=true;for(int q=0;q<a;q++)if(bool(T[a]>>q&1)!=bool(T[b]>>f[q]&1)){ok=false;break;}if(ok){f[a]=b;go(a+1,used|(1u<<b));}}};go(0,0);return count;}
bool prime_sieve(int v){vector<bool>p(v+1,true);p[0]=p[1]=false;for(int q=2;q*q<=v;q++)if(p[q])for(int z=q*q;z<=v;z+=q)p[z]=false;return p[v];}
int main(){R N{46,320,2,1014,999,966,901,775,517,7},P{46,640,2,2038,2023,1990,1927,1797,1543,1029,7};vector<R> seeds{N,P};for(int s=0;s<2;s++){auto T=seeds[s];need(!modules(T),"no homogeneous module");need(automorphisms(T)==1,"rigid source");auto a=gap(T);vector<Z>w=s?vector<Z>{521,1561,1560,520}:vector<Z>{259,779,780,260};for(int k=0;k<(int)a.size();k++)need(a[k]==(k<4?w[k]:0),"complete literal gap polynomial");int r=T.size()-1;vector<pair<int,int>>edges;for(int x=0;x<r;x++)if(T[r]>>x&1)for(int y=0;y<r;y++)if((T[y]>>r&1)&&(T[x]>>y&1))edges.push_back({x,y});need(!edges.empty(),"cross edges");for(auto[x,y]:edges)need(x==0||x==1,"two-vertex crossing cover");bool matching=false;for(auto[a,b]:edges)for(auto[c,d]:edges)if(a!=c&&b!=d)matching=true;need(matching,"rank exactly two");}
vector<tuple<int,int,Z>> cases{{0,1,779},{1,1,1561},{0,2,2339},{0,3,7019},{0,6,189539}};for(auto[s,m,h]:cases)need(walk(clone_last(seeds[s],m))==h,"independent walk witness count");for(int p:{2339,7019,223,27077})need(prime_sieve(p),"independent primality sieve");need(779==19*41&&1561==7*223&&189539==7*27077,"factor controls");cout<<"{\"status\":\"PASS\",\"module_indec_sources\":2,\"rigid_sources\":2,\"complete_literal_gap_vectors\":[[259,779,780,260],[521,1561,1560,520]],\"walk_counts\":[779,1561,2339,7019,189539],\"sieve_primes\":[2339,7019,223,27077]}\n";}
